// Demo data for Helm. Every row here is SIMULATED — generated by a seeded PRNG,
// never real student records. The institution/batch NAMING follows two real,
// verified sources so the demo reads true to the actual product:
//   1. UAT/demo institution names literally observed in FACE Prep's own real
//      Authoring Portal screenshots (campusdesk/SPEC.md, "Delivery" section):
//      Meadow Institute, Greenfield Institute of Technology, Stonebridge
//      Academy, Silverstone Academy, Northgate College, Maplewood College of
//      Science — these are FACE Prep's own placeholder test accounts, not our
//      invention.
//   2. AMET University, added as a 7th institution because that's the real
//      context this project was commissioned from (the Campus Manager's own
//      admin.faceprep.in/c/batch?...institution_id=college1459 link) — only
//      the institution NAME is real; every batch/student/question/attempt
//      under it is fabricated demo content, never actual AMET/FACE Prep data.
// Every student name, question, and score below is invented for demonstration.
import { getCollection, setCollection, nextId, COLLECTIONS } from './store.js'
import { hashPassword } from './auth.js'

// mulberry32 — small deterministic PRNG so the seed is reproducible.
function mulberry32(seed) {
  let a = seed >>> 0
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}
const rng = mulberry32(20260824)
const pick = (arr) => arr[Math.floor(rng() * arr.length)]
const int = (min, max) => min + Math.floor(rng() * (max - min + 1))
const bool = (p = 0.5) => rng() < p

const FIRST = ['Aarav', 'Diya', 'Kabir', 'Meera', 'Rohan', 'Ishita', 'Vivaan', 'Ananya', 'Aditya', 'Sara', 'Krish', 'Priya', 'Arjun', 'Neha', 'Dev', 'Tara', 'Kian', 'Riya', 'Yash', 'Anika', 'Vihaan', 'Myra', 'Reyansh', 'Zara', 'Advait', 'Kavya', 'Sai', 'Naina', 'Ayaan', 'Ira']
const LAST = ['Sharma', 'Menon', 'Iyer', 'Reddy', 'Nair', 'Gupta', 'Rao', 'Patel', 'Khan', 'Verma', 'Pillai', 'Das', 'Bose', 'Kapoor', 'Joshi', 'Mishra', 'Chatterjee', 'Bhatt']
const name = () => `${pick(FIRST)} ${pick(LAST)}`

const INSTITUTIONS = [
  { name: 'AMET University', address: 'Kanathur, Chennai, Tamil Nadu' },
  { name: 'Meadow Institute', address: '14 Willowbrook Rd' },
  { name: 'Greenfield Institute of Technology', address: '88 Elm Avenue' },
  { name: 'Stonebridge Academy', address: '221 Harbor Lane' },
  { name: 'Silverstone Academy', address: '9 Ridgeway Court' },
  { name: 'Northgate College', address: '77 Northgate Blvd' },
  { name: 'Maplewood College of Science', address: '3 Maple Terrace' },
]

const CATEGORIES = ['Aptitude', 'Coding', 'DSA', 'Communication', 'Logical Reasoning', 'Web Development', 'Python', 'DBMS']
const TOPICS = { Aptitude: ['Percentages', 'Time & Work', 'Probability'], Coding: ['Loops', 'Recursion', 'Arrays'], DSA: ['Linked List', 'Stack', 'Queue', 'Trees'], Communication: ['Grammar', 'Vocabulary', 'Reading'], 'Logical Reasoning': ['Series', 'Puzzles', 'Syllogisms'], 'Web Development': ['HTML/CSS', 'JavaScript', 'REST APIs'], Python: ['Basics', 'OOP', 'Data Structures'], DBMS: ['SQL', 'Normalization', 'Transactions'] }
const DIFFICULTIES = ['easy', 'medium', 'hard']

async function seedInstitutions() {
  const rows = []
  for (const i of INSTITUTIONS) rows.push({ id: await nextId('college'), name: i.name, address: i.address, createdAt: new Date(2025, 5, int(1, 28)).toISOString() })
  await setCollection('institutions', rows)
  return rows
}

async function seedBatches(institutions) {
  const rows = []
  const amet = institutions[0]
  // AMET gets a richer, real-shaped hierarchy (parent batches with subgroups)
  // since that's the actual use case this project targets.
  const ametBatches = [
    ['III B.Sc. AI-ML', '2024-2027'], ['II B.Sc. AI-ML', '2025-2028'], ['I B.Sc. AI-ML', '2026-2029'],
    ['I B.Sc. AI-DS', '2026-2029'], ['II B.Sc. AI-DS', '2025-2028'],
    ['I B.Tech. AI-DS', '2026-2030'], ['I B.Com. FAI', '2026-2029'], ['II B.Com. FAI', '2025-2028'],
    ['I B.B.A. EDM', '2026-2029'], ['II B.B.A. EDM', '2025-2028'],
  ]
  for (const [nm, yr] of ametBatches) {
    const parent = { id: await nextId('batch'), institutionId: amet.id, name: nm, year: yr, parentBatchId: null, createdAt: new Date(2025, 6, int(1, 28)).toISOString() }
    rows.push(parent)
    // ~40% of AMET batches get 2 placement-prep subgroups (mirrors the real
    // "Parent Batch" subgroup mechanic FACE Prep uses for split sections).
    if (bool(0.4)) {
      rows.push({ id: await nextId('batch'), institutionId: amet.id, name: `${nm} — Section A`, year: yr, parentBatchId: parent.id, createdAt: parent.createdAt })
      rows.push({ id: await nextId('batch'), institutionId: amet.id, name: `${nm} — Section B`, year: yr, parentBatchId: parent.id, createdAt: parent.createdAt })
    }
  }
  // Other institutions get a couple of generic UAT-style batches each.
  for (const inst of institutions.slice(1)) {
    for (let n = 1; n <= int(1, 3); n++) {
      rows.push({ id: await nextId('batch'), institutionId: inst.id, name: `UAT batch ${n}`, year: String(int(2027, 2029)), parentBatchId: null, createdAt: new Date(2025, 7, int(1, 28)).toISOString() })
    }
  }
  await setCollection('batches', rows)
  return rows
}

async function seedUsers(institutions, batches) {
  const rows = []
  // A handful of staff accounts across the roles the real portal defines.
  const staff = [
    { name: 'Priya Admin', email: 'admin@helm.demo', role: 'Super Admin' },
    { name: 'Ravi Coordinator', email: 'coordinator@helm.demo', role: 'Coordinator' },
    { name: 'Meera Author', email: 'author@helm.demo', role: 'Author' },
  ]
  for (const s of staff) rows.push({ id: await nextId('user'), ...s, institutionId: institutions[0].id, batchIds: [], registerNumber: '', phoneNumber: '', password: hashPassword('helm@demo123'), createdAt: new Date(2025, 5, 1).toISOString() })

  // Students distributed across leaf batches (skip parent batches that only
  // exist to group subgroups — students sit in the actual sections).
  const parentIds = new Set(batches.filter(b => batches.some(x => x.parentBatchId === b.id)).map(b => b.id))
  const leafBatches = batches.filter(b => !parentIds.has(b.id))
  for (const b of leafBatches) {
    const n = int(18, 45)
    for (let i = 0; i < n; i++) {
      const nm = name()
      rows.push({
        id: await nextId('user'), name: nm, email: `${nm.toLowerCase().replace(/\s+/g, '.')}${int(1, 999)}@helm.demo`,
        role: 'Student', institutionId: b.institutionId, batchIds: [b.id],
        registerNumber: `${b.year.slice(0, 4)}${String(int(1000, 9999))}`, phoneNumber: `9${int(100000000, 999999999)}`,
        marks10: int(60, 98), marks12: int(58, 97),
        password: hashPassword('student123'), createdAt: b.createdAt,
      })
    }
  }
  await setCollection('users', rows)
  return rows
}

async function seedQuestions() {
  const rows = []
  for (let i = 0; i < 60; i++) {
    const cat = pick(CATEGORIES)
    const topic = pick(TOPICS[cat])
    const type = bool(0.85) ? 'MCQ' : 'RC'
    const difficulty = pick(DIFFICULTIES)
    const marks = difficulty === 'easy' ? 1 : difficulty === 'medium' ? 2 : 3
    const base = {
      id: await nextId('question'), type, difficulty, totalMarks: marks, category: cat, topic,
      tags: bool(0.4) ? [topic.toLowerCase().split(' ')[0]] : [],
      title: `${topic} — Q${i + 1}`,
      createdAt: new Date(2025, 8, int(1, 28)).toISOString(),
    }
    if (type === 'MCQ') {
      const options = [`Option A for ${topic}`, `Option B for ${topic}`, `Option C for ${topic}`, `Option D for ${topic}`]
      rows.push({ ...base, text: `Sample ${difficulty} question about ${topic.toLowerCase()} (${cat}).`, options, correctOption: pick(['A', 'B', 'C', 'D']), rationale: `Explanation grounded in ${topic}.` })
    } else {
      rows.push({ ...base, passage: `A short passage about ${topic.toLowerCase()} for reading comprehension practice.`, subQuestions: [{ title: 'Sub Q1', text: `What does the passage say about ${topic.toLowerCase()}?`, options: ['A', 'B', 'C', 'D'], correctOption: 'A', marks: Math.max(1, marks - 1) }] })
    }
  }
  await setCollection('questions', rows)
  return rows
}

async function seedAssessmentsAndDelivery(institutions, batches, users, questions) {
  const assessments = []
  const configured = []
  const courses = []
  const modules = []
  const units = []
  const administrations = []
  const attempts = []

  const titles = ['Placement Readiness — Aptitude', 'Coding Fundamentals Screener', 'Communication Skills Check', 'DBMS Core Concepts', 'Logical Reasoning Sprint']
  for (const t of titles) {
    const a = { id: await nextId('assessment'), title: t, jobRole: bool() ? 'Software Engineer' : 'Analyst', roleMaturity: pick(['Entry', 'Mid']), skills: [pick(CATEGORIES)], durationMinutes: pick([15, 20, 30, 45]), createdAt: new Date(2025, 9, int(1, 20)).toISOString() }
    assessments.push(a)
    configured.push({
      id: await nextId('config_assessment'), assessmentId: a.id, difficulty: pick(DIFFICULTIES),
      shuffleQuestions: bool(0.8), shuffleOptions: bool(0.8),
      preventTabSwitching: bool(0.6), maxPageReloadCount: int(0, 3), sebConfigKey: bool(0.3) ? `seb_${Math.random().toString(36).slice(2, 10)}` : '',
      enableProtectorCode: bool(0.3), protectorCode: bool(0.3) ? String(int(100000, 999999)) : '',
      resultPublishingType: pick(['Immediate', 'Scheduled']), scheduledDate: '',
      showCorrectAnswers: bool(0.7), showSolutions: bool(0.5), allowRetake: bool(0.4),
      createdAt: a.createdAt,
    })
  }

  const courseDefs = [
    ['Problem Solving Using Programming', 'Foundational programming and DSA for placement prep.', 'Beginner'],
    ['Aptitude Mastery', 'Quantitative and logical reasoning for campus placements.', 'Intermediate'],
    ['Professional Communication', 'Workplace communication and interview readiness.', 'Beginner'],
  ]
  for (const [nm, desc, level] of courseDefs) {
    const c = { id: await nextId('course'), name: nm, description: desc, category: pick(CATEGORIES), competencyLevel: level, status: bool(0.8) ? 'Published' : 'Draft', createdAt: new Date(2025, 9, int(1, 20)).toISOString() }
    courses.push(c)
    for (let m = 1; m <= 3; m++) {
      const mod = { id: await nextId('module'), courseId: c.id, name: `Module ${m}`, order: m, description: `Module ${m} of ${nm}.`, status: 'Published' }
      modules.push(mod)
      for (let u = 1; u <= int(2, 4); u++) {
        const type = bool(0.6) ? 'Video' : 'Assessment'
        units.push({
          id: await nextId('unit'), courseId: c.id, moduleId: mod.id, name: `${nm} — Unit ${m}.${u}`, type, order: u,
          durationMinutes: type === 'Video' ? int(5, 20) : pick([15, 20, 30]), description: `Learning unit ${u} of module ${m}.`, status: 'Published',
          youtubeUrl: type === 'Video' ? '' : undefined,
          configuredAssessmentId: type === 'Assessment' ? pick(configured).id : undefined,
        })
      }
    }
  }

  // Administrations — publish a few assessments to AMET batches.
  const students = users.filter(u => u.role === 'Student')
  for (let i = 0; i < 8; i++) {
    const cfg = pick(configured)
    const targetBatches = batches.filter(b => b.institutionId === institutions[0].id).slice(0, int(1, 3))
    const publishedDaysAgo = int(-5, 20) // negative = scheduled in the future
    const admin = {
      id: await nextId('admin'), type: 'Configured Assessment', targetId: cfg.id,
      audienceType: 'Batch', audienceIds: targetBatches.map(b => b.id),
      status: publishedDaysAgo < 0 ? 'Scheduled' : publishedDaysAgo < 2 ? 'Live' : 'Completed',
      publishedAt: new Date(Date.now() - publishedDaysAgo * 86400000).toISOString(),
    }
    administrations.push(admin)

    if (admin.status !== 'Scheduled') {
      const pool = students.filter(s => targetBatches.some(b => s.batchIds.includes(b.id)))
      for (const s of pool) {
        if (!bool(0.75)) continue // not everyone attempts
        const totalScore = int(10, 30)
        const violation = bool(0.12)
        attempts.push({
          id: await nextId('attempt'), administrationId: admin.id, assessmentId: cfg.assessmentId,
          userId: s.id, userName: s.name, userEmail: s.email,
          status: violation ? 'Hard Submitted' : bool(0.15) ? 'Extended' : 'Submitted',
          obtainedScore: Math.max(0, Math.round(totalScore * (violation ? rng() * 0.4 : 0.35 + rng() * 0.6))),
          totalScore, startedAt: admin.publishedAt, endsAt: admin.publishedAt,
        })
      }
    }
  }

  await setCollection('assessments', assessments)
  await setCollection('configured_assessments', configured)
  await setCollection('courses', courses)
  await setCollection('course_modules', modules)
  await setCollection('learning_units', units)
  await setCollection('administrations', administrations)
  await setCollection('attempts', attempts)
}

export async function seedIfEmpty() {
  const existing = await getCollection('institutions')
  if (existing.length) return
  const institutions = await seedInstitutions()
  const batches = await seedBatches(institutions)
  const users = await seedUsers(institutions, batches)
  const questions = await seedQuestions()
  await seedAssessmentsAndDelivery(institutions, batches, users, questions)
  await setCollection('tags', ['javascript', 'css', 'html', 'math', 'advanced', 'basics'].map((t, i) => ({ id: `tag${i + 1}`, name: t })))
  await setCollection('logs', [{ id: 'log1', event: 'seed', at: new Date().toISOString(), extra: { note: 'Demo data seeded — all simulated.' } }])
}
